do $do$
declare run_id bigint; rid bigint; a bigint; b bigint; r record; k int;
begin
insert into public.companies(name,entity_type) select v.n,v.t from (values ($q$Activision Blizzard$q$,$q$public_company$q$),($q$OpenAI$q$,$q$private_company$q$)) v(n,t) where not exists (select 1 from public.companies c where lower(c.name)=lower(v.n));
create temp table _q(i int primary key, t text) on commit drop;
insert into _q values (1,$q$Additionally, we have a long-term strategic partnership with OpenAI.$q$),(2,$q$For example, in 
October 2023 we completed our acquisition of
Activision Blizzard
, Inc.$q$),(3,$q$Microsoft is a major investor in OpenAI and will continue to receive revenue-sharing payments.$q$),(4,$q$We have a long-term strategic partnership with OpenAI which was originally established in 2019.$q$),(5,$q$We have a long-term strategic partnership with OpenAI.$q$);
create temp table _e(n int, ty text, s text, g text, qs int[], sec text[], pct numeric, qual text, basis text, note text) on commit drop;
insert into _e values (1,$q$acquires$q$,$q$MSFT$q$,$q$Activision Blizzard$q$,$q${2}$q$::int[],$q${notes}$q$::text[],null,null,null,null),(2,$q$partners$q$,$q$MSFT$q$,$q$OpenAI$q$,$q${1,4,5}$q$::int[],$q${notes,notes,notes}$q$::text[],null,null,null,null),(3,$q$invests$q$,$q$MSFT$q$,$q$OpenAI$q$,$q${3}$q$::int[],$q${notes}$q$::text[],null,null,null,null);
create function pg_temp.nid(l text) returns bigint language sql as $f$ select id from public.companies where case l when $q$Amazon$q$ then ticker=$q$AMZN$q$ when $q$Alphabet$q$ then ticker=$q$GOOGL$q$ when $q$Microsoft$q$ then ticker=$q$MSFT$q$ when $q$NVIDIA$q$ then ticker=$q$NVDA$q$ when $q$Intel$q$ then ticker=$q$INTC$q$ when $q$Oracle$q$ then ticker=$q$ORCL$q$ when $q$AMD$q$ then ticker=$q$AMD$q$ when $q$CoreWeave$q$ then ticker=$q$CRWV$q$ when $q$TSMC$q$ then ticker=$q$TSM$q$ when $q$Tesla$q$ then ticker=$q$TSLA$q$ when $q$Uber Eats$q$ then ticker=$q$UBER$q$ when $q$MSFT$q$ then ticker=$q$MSFT$q$ else lower(name)=lower(l) end order by id limit 1 $f$;
insert into public.agent_runs(agent_name,mode,target,model,tokens_in,tokens_out,cost_usd,status,review_status) values ('filings_extraction','batch',$q$MSFT M6 group 1$q$,'claude-sonnet-5-5',169151,1272,0.5044,'completed','unreviewed') returning id into run_id;
for r in select * from _e order by n loop a := pg_temp.nid(r.s); b := pg_temp.nid(r.g); if r.ty in ('competes','partners') and a > b then rid := a; a := b; b := rid; end if; rid := null; select id into rid from public.relationships where source_id=a and target_id=b and relationship_type=r.ty order by id limit 1; if rid is null then insert into public.relationships(source_id,target_id,relationship_type,exposure_pct,exposure_qualifier,exposure_basis,exposure_as_of,source_type,status,run_id,as_of_date,note) values (a,b,r.ty,r.pct,r.qual,case when r.pct is null then 'none' else r.basis end,case when r.pct is null then null else '2025-12-31'::date end,'sec_filing','staged',run_id,'2025-12-31',r.note) returning id into rid; end if; if (select status from public.relationships where id=rid)='staged' then for k in 1..array_length(r.qs,1) loop insert into public.evidence(relationship_id,document_url,section,quote,quote_found,published_at) select rid,$q$https://www.sec.gov/Archives/edgar/data/789019/000119312526323660/msft-20260630.htm$q$,r.sec[k],t,true,$q$2026-07-29$q$ from _q where i=r.qs[k]; end loop; end if; end loop;
end $do$;